/**
 * Admin-posted, trip-scoped critical updates (2026-07-25) — "Departure moved
 * to 7am", "Coach 3 relocated to Gate B", etc. Reading is open to any
 * signed-in Staff/Admin account (same as the Dashboard/mobile Home itself);
 * only posting/editing/deleting requires the "manageAnnouncements" action
 * permission (2026-07-27 — "set permission so only admin can update/delete,
 * staff can only view, but give the permission access") — Admin always has
 * every permission (see accountPermissions()'s bypass in db/accounts.js);
 * Staff starts without it and an admin can grant it per-account from
 * Account control, same as manageTrips/manageExceptions.
 *
 * Own dedicated page (2026-07-26, AnnouncementsPage.jsx) rather than a
 * Dashboard widget — an announcement can optionally tag the itinerary stop
 * it's about and/or carry up to MAX_IMAGES photos and MAX_VIDEOS clips
 * (Cloudinary, own "mustergo/announcements" folder — see lib/cloudinary.js),
 * same memory-storage multer pattern routes/auth.js's profile-photo upload
 * uses, just .fields() for two separate file inputs (2026-07-27, "multiple
 * image upload" + "video upload also").
 *
 * Editing (2026-07-27, "give me the option to edit the announcement") is
 * PATCH /api/announcements/:id — title/message/itineraryItemId always
 * updatable; images/videos are edited by uploading new files (fields
 * "images"/"videos") and/or removing existing ones by publicId (fields
 * "removeImagePublicIds"/"removeVideoPublicIds", each a JSON-encoded array —
 * multipart fields are always strings).
 */
import { Router } from "express";
import multer from "multer";
import { wrap } from "../lib/wrap.js";
import { requireAuth, requirePermission } from "../lib/auth.js";
import { actorOf } from "../lib/actor.js";
import {
  createAnnouncement, listAnnouncements, updateAnnouncement,
  getAnnouncementImages, setAnnouncementImages,
  getAnnouncementVideos, setAnnouncementVideos,
  deleteAnnouncement,
} from "../db/announcements.js";
import { get } from "../db/connection.js";
import { resolveTripUuid } from "../data.js";
import {
  isConfigured as mediaStorageConfigured,
  uploadImage, destroyImage, uploadVideo, destroyVideo,
  ANNOUNCEMENT_FOLDER,
} from "../lib/cloudinary.js";

const router = Router();

// Caps a single announcement's media count to something a phone-frame feed
// can actually scroll through — not a hard technical limit, just sane.
const MAX_IMAGES = 6;
const MAX_VIDEOS = 2;
const MAX_VIDEO_BYTES = 25 * 1024 * 1024;

const mediaUpload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: MAX_VIDEO_BYTES, files: MAX_IMAGES + MAX_VIDEOS },
  fileFilter: (_req, file, cb) => {
    if (file.fieldname === "images" && !file.mimetype.startsWith("image/")) return cb(new Error("UNSUPPORTED_TYPE"));
    if (file.fieldname === "videos" && !file.mimetype.startsWith("video/")) return cb(new Error("UNSUPPORTED_TYPE"));
    cb(null, true);
  },
});

function handleUpload(req, res, next) {
  // Media is optional — a plain text-only announcement never has to touch
  // multer/Cloudinary at all. Wrapped rather than a plain .fields() call so a
  // bad/oversized/too-many file set returns a clean 400 instead of an
  // unhandled error.
  mediaUpload.fields([{ name: "images", maxCount: MAX_IMAGES }, { name: "videos", maxCount: MAX_VIDEOS }])(req, res, (err) => {
    if (err) {
      const code = err.message === "UNSUPPORTED_TYPE" ? "UNSUPPORTED_TYPE" : "UPLOAD_FAILED";
      const message = code === "UNSUPPORTED_TYPE"
        ? "Please upload images/videos of the right file type."
        : `Up to ${MAX_IMAGES} images + ${MAX_VIDEOS} videos, ${MAX_VIDEO_BYTES / 1024 / 1024}MB each — one file was too large, too many, or failed.`;
      return res.status(400).json({ error: code, message });
    }
    next();
  });
}

async function uploadAllImages(files) {
  if (!files?.length) return [];
  if (!mediaStorageConfigured()) {
    const err = new Error("MEDIA_STORAGE_NOT_CONFIGURED");
    err.httpStatus = 503;
    throw err;
  }
  const uploaded = [];
  for (const file of files) {
    const { url, publicId } = await uploadImage(file.buffer, ANNOUNCEMENT_FOLDER);
    uploaded.push({ url, publicId });
  }
  return uploaded;
}

async function uploadAllVideos(files) {
  if (!files?.length) return [];
  if (!mediaStorageConfigured()) {
    const err = new Error("MEDIA_STORAGE_NOT_CONFIGURED");
    err.httpStatus = 503;
    throw err;
  }
  const uploaded = [];
  for (const file of files) {
    const { url, publicId } = await uploadVideo(file.buffer, ANNOUNCEMENT_FOLDER);
    uploaded.push({ url, publicId });
  }
  return uploaded;
}

router.get("/api/trips/:id/announcements", requireAuth(), wrap(async (req, res) => {
  const tripUuid = await resolveTripUuid(req.params.id);
  res.json({ announcements: await listAnnouncements(tripUuid) });
}));

router.post("/api/trips/:id/announcements", requirePermission("manageAnnouncements"), handleUpload, wrap(async (req, res) => {
  const tripUuid = await resolveTripUuid(req.params.id);
  let title = (req.body?.title || "").trim();
  const message = (req.body?.message || "").trim();
  const itineraryItemId = req.body?.itineraryItemId || null;

  // Auto-fill the title from the tagged itinerary stop when the caller
  // didn't type one (2026-07-26 — "so user just need to put the image can
  // already" — posting a photo update for a stop shouldn't require typing
  // a title/message by hand). The frontend already does this client-side;
  // this is the server-side fallback for any other caller. Message stays
  // genuinely optional — an image-only post with no caption is valid.
  if (!title && itineraryItemId) {
    const stop = await get(`SELECT title, start_time AS "startTime" FROM itinerary_items WHERE id = $1 AND trip_id = $2`, [itineraryItemId, tripUuid]);
    if (stop) title = stop.startTime ? `${stop.title} · ${stop.startTime}` : stop.title;
  }
  if (!title) return res.status(400).json({ error: "TITLE_REQUIRED", message: "A title is required." });

  let images, videos;
  try {
    images = await uploadAllImages(req.files?.images);
    videos = await uploadAllVideos(req.files?.videos);
  } catch (err) {
    if (err.httpStatus) return res.status(err.httpStatus).json({ error: err.message, message: "Media storage isn't set up on this server yet." });
    throw err;
  }

  const announcement = await createAnnouncement(
    { tripId: tripUuid, itineraryItemId, title, message, images, videos },
    actorOf(req) || "Admin"
  );
  res.status(201).json({ announcement });
}));

router.patch("/api/announcements/:id", requirePermission("manageAnnouncements"), handleUpload, wrap(async (req, res) => {
  const title = (req.body?.title || "").trim();
  const message = (req.body?.message || "").trim();
  const itineraryItemId = req.body?.itineraryItemId || null;
  if (!title) return res.status(400).json({ error: "TITLE_REQUIRED", message: "A title is required." });

  const updated = await updateAnnouncement(req.params.id, { title, message, itineraryItemId }, actorOf(req) || "Admin");
  if (updated.error) return res.status(404).json(updated);

  // Media edits (2026-07-27) — remove whichever existing ones the caller
  // asked to drop, then append whatever new files came in. Computed in JS
  // against the current array rather than a SQL add/remove op (see
  // db/announcements.js's setAnnouncementImages doc for why). Images and
  // videos are handled as two entirely separate arrays/uploads since they
  // hit different Cloudinary upload/destroy calls (resource_type differs).
  let removeImageIds = [], removeVideoIds = [];
  try { removeImageIds = JSON.parse(req.body?.removeImagePublicIds || "[]"); } catch { /* ignore malformed */ }
  try { removeVideoIds = JSON.parse(req.body?.removeVideoPublicIds || "[]"); } catch { /* ignore malformed */ }
  const removeImageSet = new Set(Array.isArray(removeImageIds) ? removeImageIds : []);
  const removeVideoSet = new Set(Array.isArray(removeVideoIds) ? removeVideoIds : []);

  let finalImages = updated.images || [];
  let finalVideos = updated.videos || [];

  if (removeImageSet.size || req.files?.images?.length) {
    const current = await getAnnouncementImages(req.params.id);
    const kept = current.filter((img) => !removeImageSet.has(img.publicId));
    let added;
    try {
      added = await uploadAllImages(req.files?.images);
    } catch (err) {
      if (err.httpStatus) return res.status(err.httpStatus).json({ error: err.message, message: "Media storage isn't set up on this server yet." });
      throw err;
    }
    finalImages = await setAnnouncementImages(req.params.id, [...kept, ...added]);
    const removed = current.filter((img) => removeImageSet.has(img.publicId));
    await Promise.all(removed.map((img) => destroyImage(img.publicId)));
  }

  if (removeVideoSet.size || req.files?.videos?.length) {
    const current = await getAnnouncementVideos(req.params.id);
    const kept = current.filter((v) => !removeVideoSet.has(v.publicId));
    let added;
    try {
      added = await uploadAllVideos(req.files?.videos);
    } catch (err) {
      if (err.httpStatus) return res.status(err.httpStatus).json({ error: err.message, message: "Media storage isn't set up on this server yet." });
      throw err;
    }
    finalVideos = await setAnnouncementVideos(req.params.id, [...kept, ...added]);
    const removed = current.filter((v) => removeVideoSet.has(v.publicId));
    await Promise.all(removed.map((v) => destroyVideo(v.publicId)));
  }

  res.json({ announcement: { ...updated, images: finalImages, videos: finalVideos } });
}));

router.delete("/api/announcements/:id", requirePermission("manageAnnouncements"), wrap(async (req, res) => {
  const result = await deleteAnnouncement(req.params.id);
  if (result.error) return res.status(404).json(result);
  await Promise.all([
    ...(result.imagePublicIds || []).map((id) => destroyImage(id)),
    ...(result.videoPublicIds || []).map((id) => destroyVideo(id)),
  ]);
  res.json({ ok: true });
}));

export default router;
